<?php $title='Registre des inscriptions'; $subtitle='États actuellement enregistrés pour ce cours.'; $section='courses'; require __DIR__.'/management_header.php';
$url=static fn(int $p): string => 'course_bookings?'.http_build_query(['id'=>(int)$course['id'],'status'=>$status,'p'=>$p]); ?>
<section class="card management-table"><div class="card-head"><div><h3><?= e($course['title']) ?></h3><p><?= e(date('d/m/Y H:i',strtotime($course['starts_at']))) ?> · <?= e($course['room']) ?> · <?= $course['status']==='cancelled' ? 'Cours annulé' : 'Cours planifié' ?> · <?= (int)$result['total'] ?> inscription(s)</p></div><a class="text-link" href="courses?course=<?= (int)$course['id'] ?>&amp;filter=1">← Inscriptions du cours</a></div>
<form method="get" action="course_bookings" class="search-form"><input type="hidden" name="id" value="<?= (int)$course['id'] ?>"><label>Statut <select name="status"><option value="">Tous</option><?php foreach (CourseBookings::STATUS as $key=>$label): ?><option value="<?= e($key) ?>" <?= $status===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="primary">Filtrer</button><a class="text-link" href="course_bookings?id=<?= (int)$course['id'] ?>">Effacer</a></form>
<?php if (!$error): ?><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>STATUT ACTUEL</th><th>DERNIÈRE INSCRIPTION</th><th>DERNIÈRE MISE À JOUR</th></tr></thead><tbody><?php foreach ($result['rows'] as $row): ?><tr><td><?= e($row['first_name'].' '.$row['last_name']) ?></td><td><?= e(CourseBookings::STATUS[$row['status']] ?? $row['status']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($row['created_at']))) ?></td><td><?= e(date('d/m/Y H:i',strtotime($row['updated_at']))) ?></td></tr><?php endforeach; ?><?php if (!$result['rows']): ?><tr><td colspan="4" class="empty">Aucune inscription pour ce filtre.</td></tr><?php endif; ?></tbody></table></div><nav class="pagination" aria-label="Pages des inscriptions"><?php if ($result['page']>1): ?><a href="<?= e($url($result['page']-1)) ?>">← Précédent</a><?php endif; ?><span>Page <?= (int)$result['page'] ?> / <?= (int)$result['pages'] ?></span><?php if ($result['page']<$result['pages']): ?><a href="<?= e($url($result['page']+1)) ?>">Suivant →</a><?php endif; ?></nav><?php endif; ?><p class="form-hint">Ce registre affiche uniquement l’état actuel de chaque membre. Une réinscription réutilise la même ligne : les annulations, promotions et inscriptions précédentes ne sont pas conservées séparément. Les noms et les informations du cours sont les valeurs actuelles.</p></section>
